tokens.css:
--color-bg: #1c1810;
--color-surface: #2a2418;
--color-text: #f6f1e6;
--color-text-muted: #b3a88f;
--color-border: #41392a;
--color-primary: #ffcc00;
--color-on-primary: #1c1810;
--color-accent: #e0a526;
--color-on-accent: #1c1810;
--font-display: "Big Shoulders Display", system-ui, sans-serif;
--font-body: "Instrument Sans", system-ui, sans-serif;
--text-sm: 13px;
--text-base: 16px;
--text-lg: 20px;
--text-xl: 25px;
--text-2xl: 31px;
--text-3xl: 39px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 80px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
